// Writes SevenBridges/Demo/Map.lean from the map generator. Generated file: don't edit it by hand.
// Usage: node emit-demo-map.mjs <seed> <blocks> <out.lean>
// The routes and bridge sites below are picked by hand for seed 7, 7 blocks.
import { writeFileSync } from "node:fs";
import { generateMap, streetPath } from "./genmap.mjs";

const [seed, n, out] = [Number(process.argv[2]), Number(process.argv[3]), process.argv[4]];
// The demo puzzle's fixed blocks refer to this numbering: keep the original order.
const m = generateMap(seed, n, { reorder: false });

const segIndex = (a, b) => m.segments.findIndex((s) => (s.a === a && s.b === b) || (s.a === b && s.b === a));
const river = m.segments.map((s, i) => (s.terrain === "stream" ? i : -1)).filter((i) => i >= 0);

// Bridge sites: every river segment except the one between blocks 0 and 1.
const bridgeSites = river.filter((i) => segIndex(7, 8) !== i);
// Crosstown crosses the river along segment 0-8, Northside along 10-13.
const routes = [
  { name: "Crosstown", path: streetPath(m, 1, 30) },
  { name: "Northside", path: streetPath(m, 25, 30) },
];
for (const r of routes) r.path.forEach((v, i) => {
  if (i > 0 && segIndex(r.path[i - 1], v) < 0) throw new Error(`${r.name}: no segment ${r.path[i - 1]}-${v}`);
});

const lean = `-- Generated by tools/emit-demo-map.mjs (seed ${seed}, ${n} blocks). Don't edit by hand.
import SevenBridges.Rules.Puzzle

namespace SevenBridges.Demo

def demoMap : RoadMap where
  points := [${m.points.map((p) => `⟨${p.x}, ${p.y}⟩`).join(", ")}]
  segments := [${m.segments.map((s) => `{ a := ${s.a}, b := ${s.b}${s.terrain === "stream" ? ", terrain := .stream" : ""} }`).join(", ")}]
  blocks := [${m.blocks.map((b) => `⟨[${b.corners.join(", ")}]⟩`).join(",\n    ")}]

def demoRoutes : List Route :=
  [${routes.map((r) => `{ name := "${r.name}", path := [${r.path.join(", ")}] }`).join(",\n   ")}]

/-- River segments where a bridge may be built. -/
def demoBridgeSites : List Nat := [${bridgeSites.join(", ")}]

end SevenBridges.Demo
`;
writeFileSync(out, lean);
console.log(routes.map((r) => r.name + ": " + r.path.join(" ")).join("\n"));
console.log("river segments", river.join(" "), "bridge sites", bridgeSites.join(" "));
